package run.ikaros.finance; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; @RestController @RequestMapping("/api/finance/ledgers/{ledgerId}/members") public class LedgerMemberController{private final LedgerMemberService service;public LedgerMemberController(LedgerMemberService s){service=s;}@PostMapping public Mono<LedgerMemberView> add(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID ledgerId,@Valid@RequestBody AddLedgerMemberRequest r){return service.add(a,ledgerId,r);}@GetMapping public Flux<LedgerMemberView> list(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID ledgerId){return service.list(a,ledgerId);}@DeleteMapping("/{principalId}")public Mono<Void> remove(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID ledgerId,@PathVariable UUID principalId){return service.remove(a,ledgerId,principalId);}}
